// exec updates the rows and their edges, in one transaction, and returns how
// many there were.
pub fn (b PostUpdate) exec() !int {
	return b.graph.client.update(b.data)
}

// PostDeleteOne builds the delete of one `posts` row. Start one with
// `Graph.posts().delete_one(node)` or `delete_one_id(id)`.
pub struct PostDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q PostQuery) delete_one(node PostNode) PostDeleteOne {
	return q.delete_one_id(node.post.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q PostQuery) delete_one_id(id int) PostDeleteOne {
	return PostDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'posts'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b PostDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'posts'
		}
	}
}

// PostDelete builds the delete of the `posts` rows that match its conditions.
// Start one with `Graph.posts().delete()`.
pub struct PostDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q PostQuery) delete() PostDelete {
	return PostDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'posts'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b PostDelete) where(conds ...load.Cond) PostDelete {
	return PostDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

